<?php require_once __DIR__.'/../includes/bootstrap.php';require_role(['admin','librarian']);verify_csrf();$id=(int)($_POST['id']??0);$a=$_POST['action']??'';$actor=(int)current_user()['id'];try{$conn->begin_transaction();$s=$conn->prepare('SELECT * FROM borrowings WHERE id=? FOR UPDATE');$s->bind_param('i',$id);$s->execute();$r=$s->get_result()->fetch_assoc();if(!$r)throw new Exception('Record not found.');$bid=(int)$r['book_id'];if($a==='approve'&&$r['status']==='pending'){$s=$conn->prepare("UPDATE borrowings SET status='approved',approved_by=?,approved_at=NOW() WHERE id=? AND status='pending'");$s->bind_param('ii',$actor,$id);$s->execute();$detail='Approved borrowing #'.$id;}elseif($a==='reject'&&$r['status']==='pending'){$s=$conn->prepare("UPDATE borrowings SET status='rejected',approved_by=?,approved_at=NOW() WHERE id=? AND status='pending'");$s->bind_param('ii',$actor,$id);$s->execute();$detail='Rejected borrowing #'.$id;}elseif($a==='release'&&$r['status']==='approved'){$s=$conn->prepare('SELECT available_copies FROM books WHERE id=? FOR UPDATE');$s->bind_param('i',$bid);$s->execute();$b=$s->get_result()->fetch_assoc();if(!$b||$b['available_copies']<1)throw new Exception('No available copies remain.');$s=$conn->prepare("SELECT id FROM reservations WHERE book_id=? AND status IN('pending','approved','ready') ORDER BY id LIMIT 1 FOR UPDATE");$s->bind_param('i',$bid);$s->execute();if($s->get_result()->num_rows)throw new Exception('An active reservation queue has priority. Process reservations first.');$s=$conn->prepare('UPDATE books SET available_copies=available_copies-1 WHERE id=? AND available_copies>0');$s->bind_param('i',$bid);$s->execute();if(!$s->affected_rows)throw new Exception('Inventory changed; retry.');$due=date('Y-m-d',strtotime('+14 days'));$s=$conn->prepare("UPDATE borrowings SET status='borrowed',released_by=?,released_at=NOW(),due_date=? WHERE id=? AND status='approved'");$s->bind_param('isi',$actor,$due,$id);$s->execute();$detail='Released borrowing #'.$id;}elseif($a==='return'&&$r['status']==='borrowed'){$s=$conn->prepare("UPDATE borrowings SET status='returned',returned_by=?,returned_at=NOW() WHERE id=? AND status='borrowed'");$s->bind_param('ii',$actor,$id);$s->execute();if(!$s->affected_rows)throw new Exception('Already processed.');$s=$conn->prepare('UPDATE books SET available_copies=LEAST(total_copies,available_copies+1) WHERE id=?');$s->bind_param('i',$bid);$s->execute();$detail='Returned borrowing #'.$id;}else throw new Exception('Invalid action for this status.');$conn->commit();log_activity($conn,$actor,'borrowing_'.$a,$detail);flash('success',$detail);}catch(Throwable $e){$conn->rollback();flash('error',$e->getMessage());}redirect('borrowings.php');?>